import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LocalDateTime_fromCalendarFields_TriageGen2Test {





    @Test
    public void testFromCalendarFields_BC() {
        // Test for BC era (Branch coverage: era != GregorianCalendar.AD)
        // In GregorianCalendar, BC is represented by ERA = BCE
        Calendar calendar = new GregorianCalendar();
        calendar.set(1, Calendar.JANUARY, 1, 0, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);
        calendar.set(Calendar.ERA, GregorianCalendar.BC);

        // Note: The logic in the provided method is: (era == AD ? yearOfEra : 1 + yearOfEra)
        // If era is BC and yearOfEra is 1, result year should be 2.
        int yearOfEra = calendar.get(Calendar.YEAR);
        calendar.set(Calendar.YEAR, yearOfEra);

        LocalDateTime result = LocalDateTime.fromCalendarFields(calendar);

        assertEquals(1 + yearOfEra, result.getYear());
        assertEquals(1, result.getMonthOfYear());
        assertEquals(1, result.getDayOfMonth());
        assertEquals(0, result.getHourOfDay());
        assertEquals(0, result.getMinuteOfHour());
        assertEquals(0, result.getSecondOfMinute());
        assertEquals(0, result.getMillisOfSecond());
    }


}

